import static org.mockito.Mockito.when;

public class DatasetUtilities_iterateDomainBounds_TriageGen2Test {

    @Mock
    private XYDataset mockXYDataset;

    @Mock
    private IntervalXYDataset mockIntervalXYDataset;

    public DatasetUtilities_iterateDomainBounds_TriageGen2Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIterateDomainBounds_NullDataset() {
        DatasetUtilities.iterateDomainBounds(null, false);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_SingleSeries() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(1.0);
        when(mockXYDataset.getXValue(0, 1)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(1.0, result.getLower(), 1e-10);
        assertEquals(5.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_WithNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(3);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(1.0);
        when(mockXYDataset.getXValue(0, 1)).thenReturn(Double.NaN);
        when(mockXYDataset.getXValue(0, 2)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(1.0, result.getLower(), 1e-10);
        assertEquals(10.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval() {
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);
        // Test interval bounds: [2.0, 8.0]
        when(mockIntervalXYDataset.getStartXValue(0, 0)).thenReturn(2.0);
        when(mockIntervalXYDataset.getEndXValue(0, 0)).thenReturn(8.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, true);

        assertEquals(2.0, result.getLower(), 1e-10);
        assertEquals(8.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_WithNaN() {
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(2);

        // First item: valid interval
        when(mockIntervalXYDataset.getStartXValue(0, 0)).thenReturn(1.0);
        when(mockIntervalXYDataset.getEndXValue(0, 0)).thenReturn(3.0);

        // Second item: NaN start, valid end
        when(mockIntervalXYDataset.getStartXValue(0, 1)).thenReturn(Double.NaN);
        when(mockIntervalXYDataset.getEndXValue(0, 1)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, true);

        assertEquals(1.0, result.getLower(), 1e-10);
        assertEquals(5.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_NaNEnd() {
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);

        when(mockIntervalXYDataset.getStartXValue(0, 0)).thenReturn(1.0);
        when(mockIntervalXYDataset.getEndXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, true);

        assertEquals(1.0, result.getLower(), 1e-10);
        assertEquals(1.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_EmptyDataset() {
        when(mockXYDataset.getSeriesCount()).thenReturn(0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_DatasetWithOnlyNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_IncludeInterval_False_On_IntervalDataset() {
        // Even if it is an IntervalXYDataset, if includeInterval is false, it should use getXValue
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);
        // Mocking getXValue for the IntervalXYDataset (assuming it implements XYDataset)
        when(mockIntervalXYDataset.getXValue(0, 0)).thenReturn(4.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, false);

        assertEquals(4.0, result.getLower(), 1e-10);
        assertEquals(4.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_MultipleSeries() {
        when(mockXYDataset.getSeriesCount()).thenReturn(2);

        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(0.0);

        when(mockXYDataset.getItemCount(1)).thenReturn(1);
        when(mockXYDataset.getXValue(1, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(0.0, result.getLower(), 1e-10);
        assertEquals(10.0, result.getUpper(), 1e-10);
    }
}
